const MAP_W = 1000;
const MAP_H = 500;

/* ---------- Helpers ---------- */
function project(lat, lng) {
  const x = (lng + 180) / 360 * MAP_W;
  const y = (90 - lat) / 180 * MAP_H;
  return { x, y };
}

function haversineKm(a, b) {
  const R = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

/* ---------- Arc geometry (pure math, no DOM) ----------
   A leg's visual path is a quadratic Bézier: start point, a control point
   bowed toward the top of the screen, and the end point. Keeping the geometry
   in pure functions (instead of SVG DOM getPointAtLength) makes playback
   deterministic and seekable — the foundation for MP4 export later. */
function legBezier(from, to) {
  const a = project(from.lat, from.lng);
  const b = project(to.lat, to.lng);
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2;
  let nx = -dy / dist;
  let ny = dx / dist;
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  } // always bow toward top of screen
  const bow = Math.min(dist * 0.28, 90);
  return {
    p0: a,
    p1: { x: mx + nx * bow, y: my + ny * bow }, // control point
    p2: b,
  };
}

function qPoint(bz, t) {
  const u = 1 - t;
  const x = u * u * bz.p0.x + 2 * u * t * bz.p1.x + t * t * bz.p2.x;
  const y = u * u * bz.p0.y + 2 * u * t * bz.p1.y + t * t * bz.p2.y;
  return { x, y };
}

function qTangent(bz, t) {
  const u = 1 - t;
  // Derivative of the quadratic Bézier
  const x = 2 * (u * (bz.p1.x - bz.p0.x) + t * (bz.p2.x - bz.p1.x));
  const y = 2 * (u * (bz.p1.y - bz.p0.y) + t * (bz.p2.y - bz.p1.y));
  return { x, y };
}

/** Arc-length lookup table: lets us move along the curve at constant speed.
 *  samples[i] = { t, len } — cumulative length from t=0 to t=sample.t */
function buildArcLUT(bz, n = 64) {
  const samples = [{ t: 0, len: 0 }];
  let len = 0;
  let prev = qPoint(bz, 0);
  for (let i = 1; i <= n; i++) {
    const t = i / n;
    const cur = qPoint(bz, t);
    len += Math.hypot(cur.x - prev.x, cur.y - prev.y);
    samples.push({ t, len });
    prev = cur;
  }
  return { samples, total: len };
}

/** Fraction f in [0,1] of arc length → parametric t on the curve */
function tAtFraction(lut, f) {
  const target = Math.max(0, Math.min(1, f)) * lut.total;
  // binary search over cumulative lengths
  let lo = 0;
  let hi = lut.samples.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (lut.samples[mid].len <= target) lo = mid;
    else hi = mid;
  }
  const a = lut.samples[lo];
  const b = lut.samples[hi];
  const seg = b.len - a.len;
  const local = seg > 0 ? (target - a.len) / seg : 0;
  return a.t + local * (b.t - a.t);
}

function arcPath(from, to) {
  const bz = legBezier(from, to);
  return `M${bz.p0.x.toFixed(1)},${bz.p0.y.toFixed(1)} Q${bz.p1.x.toFixed(1)},${bz.p1.y.toFixed(1)} ${bz.p2.x.toFixed(1)},${bz.p2.y.toFixed(1)}`;
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

function formatDateShort(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short' }).toUpperCase();
}

/* ---------- Photo compression (NFR2: respect the 5MB storage ceiling) ----------
   Photos are compressed to JPEG at a max dimension of 800px and quality 0.7,
   producing data URLs typically under 100KB. Stored under a per-stop
   localStorage key so a large photo can't corrupt the main trip record. */
const PHOTO_MAX_DIM = 800;
const PHOTO_QUALITY = 0.7;
const PHOTO_STORAGE_PREFIX = 'flight-log:photo:';

function compressImage(file) {
  return new Promise((resolve, reject) => {
    if (!file.type.startsWith('image/')) {
      reject(new Error('Please choose an image file'));
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > PHOTO_MAX_DIM || height > PHOTO_MAX_DIM) {
          const scale = PHOTO_MAX_DIM / Math.max(width, height);
          width = Math.round(width * scale);
          height = Math.round(height * scale);
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        const dataUrl = canvas.toDataURL('image/jpeg', PHOTO_QUALITY);
        resolve(dataUrl);
      };
      img.onerror = () => reject(new Error('Could not load image'));
      img.src = reader.result;
    };
    reader.onerror = () => reject(new Error('Could not read file'));
    reader.readAsDataURL(file);
  });
}

function savePhoto(photoId, dataUrl) {
  try {
    localStorage.setItem(PHOTO_STORAGE_PREFIX + photoId, dataUrl);
  } catch (e) {
    console.error('Could not save photo (storage full?)', e);
  }
}

function loadPhoto(photoId) {
  try {
    return localStorage.getItem(PHOTO_STORAGE_PREFIX + photoId);
  } catch (e) {
    return null;
  }
}

function deletePhoto(photoId) {
  try {
    localStorage.removeItem(PHOTO_STORAGE_PREFIX + photoId);
  } catch (e) {
    /* ignore */
  }
}

/* ---------- Camera (Stage 4: vertical + camera-follow) ----------
   Pure function computing the output viewport from the timeline.
   Returns {cx, cy, zoom}: the map-space point at the center of the
   output frame and the scale factor (1 = whole map visible).
   During a leg the camera frames the active Bézier region; during a
   stop pause it zooms in on the arrived pin. Deterministic — same t,
   same camera. */
const OUT_W = 562;  // 9:16 at half map-width scale
const OUT_H = 1000;
const HORIZ_W = 1000;
const HORIZ_H = 500;

function legBounds(bz) {
  const minX = Math.min(bz.p0.x, bz.p1.x, bz.p2.x);
  const maxX = Math.max(bz.p0.x, bz.p1.x, bz.p2.x);
  const minY = Math.min(bz.p0.y, bz.p1.y, bz.p2.y);
  const maxY = Math.max(bz.p0.y, bz.p1.y, bz.p2.y);
  return { minX, maxX, minY, maxY };
}

function cameraAt(frame, legs, outW, outH) {
  if (!legs.length) return { cx: MAP_W / 2, cy: MAP_H / 2, zoom: 1 };
  const leg = legs[Math.min(frame.legIndex, legs.length - 1)];
  const bz = leg.bz;

  let cx, cy, zoom;

  if (frame.pausedAtStopIndex !== null) {
    // Dwelling at a stop: zoom onto the arrived pin.
    const stopIdx = Math.min(frame.pausedAtStopIndex, legs.length); // stops.length when finished
    // The arrived stop's position: pause after leg i = stop i+1 = leg[i].to
    const pin = frame.pausedAtStopIndex >= legs.length ? bz.p2 : legs[frame.pausedAtStopIndex - 1].bz.p2;
    cx = pin.x;
    cy = pin.y;
    zoom = Math.min(3.2, Math.max(2.2, (outW / MAP_W) * 4));
  } else {
    // Flying a leg: frame the whole leg with comfortable padding.
    const b = legBounds(bz);
    cx = (b.minX + b.maxX) / 2;
    cy = (b.minY + b.maxY) / 2;
    const legW = Math.max(b.maxX - b.minX, 40);
    const legH = Math.max(b.maxY - b.minY, 40);
    // zoom such that the leg's bounding box (plus padding) fits the output
    const zoomX = outW / (legW * 1.9);
    const zoomY = outH / (legH * 1.9);
    zoom = Math.min(3.5, Math.max(0.8, Math.min(zoomX, zoomY)));
  }

  // Clamp the camera so we don't show empty space beyond the map edges.
  const halfW = outW / (2 * zoom);
  const halfH = outH / (2 * zoom);
  cx = Math.max(halfW, Math.min(MAP_W - halfW, cx));
  cy = Math.max(halfH, Math.min(MAP_H - halfH, cy));
  if (outW / (2 * zoom) >= MAP_W / 2) cx = MAP_W / 2;
  if (outH / (2 * zoom) >= MAP_H / 2) cy = MAP_H / 2;

  return { cx, cy, zoom };
}

/** Smoothstep easing for camera blending between keyframes. */
function smoothstep(t) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}

/* ---------- Stop data model ----------
    Stops are ordered manually via an `order` field (the real sort key).
    `date` is an optional, display-only label. `caption` is an optional
    one-line note shown in tooltips and (later) video postcard reveals.

   Migration: legacy stops (pre-order field) are assigned order values
   based on their existing date-sort, so old saved trips load unchanged. */
function migrateStops(rawStops) {
  if (!Array.isArray(rawStops)) return [];
  const withFallback = rawStops.map((s, i) => ({
    ...s,
    order: typeof s.order === 'number' && Number.isFinite(s.order) ? s.order : i,
  }));
  // Assign canonical order values (0..n-1) by current sort: legacy order
  // (date first for un-migrated stops, then existing order field).
  const dated = withFallback.filter((s) => s.date);
  const undated = withFallback.filter((s) => !s.date);
  const sortedByDate = [...dated].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  // Stable interleave: dated stops keep their date positions; undated go last,
  // in arrival order — matching what a user saw before migration.
  const legacySequence = [];
  let di = 0, ui = 0;
  for (const s of withFallback) {
    legacySequence.push(s.date ? sortedByDate[di++] : undated[ui++]);
  }
  return legacySequence.map((s, i) => ({ ...s, order: i }));
}

function sortStops(stops) {
  return [...stops].sort((a, b) => {
    if (a.order !== b.order) return a.order - b.order;
    // Stable tiebreak for stops created before order settled
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
}
/* ---------- Small plane glyph, nose points to +x (east) at rotation 0 ----------
   A proper twin-engine aircraft silhouette: fuselage, swept wings, tail.
   Designed at ~20px wingspan; reads as "airplane" at the map scale. */
const PLANE_PATH = 'M 10,0 L 4,-1.2 L 1,-6 L -1,-6 L -1.5,-2 L -5,-3.5 L -6,-3 L -4,-1 L -6.5,-0.8 L -9,-2.5 L -11,-2 L -9,-0.3 L -11,0.3 L -9,2 L -11,2.5 L -9,2.5 L -6.5,0.8 L -4,1 L -6,3 L -5,3.5 L -1.5,2 L -1,6 L 1,6 L 4,1.2 Z';

function PlaneGlyph({ x, y, angle, color }) {
  return (
    <g transform={`translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${angle.toFixed(1)})`}>
      <path d={PLANE_PATH} fill={color} stroke={COLORS.navyDeep} strokeWidth="0.5" strokeLinejoin="round" />
    </g>
  );
}

/* ---------- Canvas rendering (video export path) ----------
   Draws one frame of the map + route + plane to a 2D canvas context.
   Mirrors the SVG render exactly: same colors, same geometry helpers,
   driven by the same pure stateAt(t) frame the interactive view uses.
   Uses Path2D for the land-mass (parsed once, cached). */
let landPath2D = null;
function getLandPath2D() {
  if (!landPath2D) landPath2D = new Path2D(LAND_PATH);
  return landPath2D;
}

let planePath2D = null;
function getPlanePath2D() {
  if (!planePath2D) planePath2D = new Path2D(PLANE_PATH);
  return planePath2D;
}

function drawFrame(ctx, { frame, legs, sortedStops, totalKm, tripTitle, photoImages, outW = MAP_W, outH = MAP_H, useCamera = false, cam = null }) {
  const W = outW, H = outH;
  ctx.clearRect(0, 0, W, H);

  // ---- Map layer (optionally camera-transformed) ----
  ctx.save();
  if (useCamera && cam) {
    // Camera transform: map-space (cx,cy) lands at output center, scaled by zoom.
    ctx.translate(W / 2 - cam.cx * cam.zoom, H / 2 - cam.cy * cam.zoom);
    ctx.scale(cam.zoom, cam.zoom);
  }
  const W_MAP = MAP_W, H_MAP = MAP_H;

  // Background
  ctx.fillStyle = COLORS.navy;
  ctx.fillRect(0, 0, W_MAP, H_MAP);

  // Graticule
  ctx.strokeStyle = COLORS.fog;
  ctx.globalAlpha = 0.1;
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  for (const lng of [-150, -120, -90, -60, -30, 0, 30, 60, 90, 120, 150]) {
    const x = ((lng + 180) / 360) * W_MAP;
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H_MAP);
  }
  for (const lat of [-60, -30, 0, 30, 60]) {
    const y = ((90 - lat) / 180) * H_MAP;
    ctx.moveTo(0, y);
    ctx.lineTo(W_MAP, y);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Landmass
  ctx.fillStyle = COLORS.parchment;
  ctx.strokeStyle = COLORS.navyDeep;
  ctx.lineWidth = 0.6;
  ctx.fill(getLandPath2D());
  ctx.stroke(getLandPath2D());

  // Route legs: contrail glow under flown/current + main line (dashed for future)
  legs.forEach((leg, i) => {
    const bz = leg.bz;
    const isCurrent = i === frame.legIndex;
    const isPast = i < frame.legIndex;
    const isFuture = i > frame.legIndex;
    // Contrail glow
    if (isPast || isCurrent) {
      ctx.strokeStyle = COLORS.ember;
      ctx.globalAlpha = isCurrent ? 0.18 : 0.1;
      ctx.lineWidth = isCurrent ? 5 : 3.5;
      ctx.setLineDash([]);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(bz.p0.x, bz.p0.y);
      ctx.quadraticCurveTo(bz.p1.x, bz.p1.y, bz.p2.x, bz.p2.y);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
    // Main line
    ctx.strokeStyle = isFuture ? COLORS.emberDim : COLORS.ember;
    ctx.lineWidth = isCurrent ? 1.8 : isPast ? 1.4 : 1.1;
    ctx.setLineDash(isFuture ? [4, 3] : []);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(bz.p0.x, bz.p0.y);
    ctx.quadraticCurveTo(bz.p1.x, bz.p1.y, bz.p2.x, bz.p2.y);
    ctx.stroke();
  });
  ctx.setLineDash([]);

  // Stop pins
  sortedStops.forEach((s, i) => {
    const p = project(s.lat, s.lng);
    const isPast = frame.isPast(i);
    ctx.beginPath();
    ctx.arc(p.x, p.y, 7, 0, Math.PI * 2);
    ctx.fillStyle = isPast ? COLORS.brass : COLORS.paper;
    ctx.fill();
    ctx.strokeStyle = COLORS.navyDeep;
    ctx.lineWidth = 1;
    ctx.stroke();
    // Pin number
    ctx.fillStyle = COLORS.navyDeep;
    ctx.font = '700 8.5px "Space Mono", monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(i + 1), p.x, p.y + 0.5);
  });

  // Plane glyph (proper aircraft silhouette, nose points +x at rotation 0)
  if (frame.plane) {
    const { x, y, angle } = frame.plane;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate((angle * Math.PI) / 180);
    ctx.fillStyle = COLORS.ember;
    ctx.fill(getPlanePath2D());
    ctx.strokeStyle = COLORS.navyDeep;
    ctx.lineWidth = 0.5;
    ctx.lineJoin = 'round';
    ctx.stroke(getPlanePath2D());
    ctx.restore();
  }
  ctx.restore(); // end camera transform

  // ---- Overlay layer (output coordinates) ----

  // Title card (top-left overlay)
  if (tripTitle) {
    ctx.font = '700 13px "Space Mono", monospace';
    ctx.fillStyle = COLORS.brass;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('ROUTE ATLAS', 24, 34);
    ctx.font = '600 26px Fraunces, Georgia, serif';
    ctx.fillStyle = COLORS.parchment;
    ctx.fillText(tripTitle, 24, 64);
    if (totalKm > 0) {
      ctx.font = '400 12px "Space Mono", monospace';
      ctx.fillStyle = COLORS.fog;
      ctx.fillText(`${totalKm.toLocaleString()} km`, 24, 86);
    }
  }

  // Postcard reveal: when the plane is dwelling at a stop with a photo,
  // draw the photo as a postcard overlay that slides up from the bottom.
  // pauseProgress (0..1) drives the animation: slide-in during first 25%,
  // hold during middle, slide-out during last 25%.
  if (frame.pausedAtStopIndex !== null && frame.pauseProgress !== undefined && photoImages) {
    const stopIdx = frame.pausedAtStopIndex;
    const stop = sortedStops[stopIdx];
    if (stop) {
      const img = photoImages[stop.id];
      if (img && img.width > 0) {
        // Animate the postcard Y offset based on pause progress with easing.
        const pp = frame.pauseProgress;
        let slideOffset = 0; // 0 = fully visible, 1 = fully below screen
        if (pp < 0.25) {
          // Sliding in: ease from below (offset=1) to visible (offset=0)
          slideOffset = 1 - smoothstep(pp / 0.25);
        } else if (pp > 0.75) {
          // Sliding out: ease from visible (offset=0) to below (offset=1)
          slideOffset = smoothstep((pp - 0.75) / 0.25);
        }
        // Postcard sized relative to the output frame
        const pcW = Math.min(480, W * 0.82);
        const pcH = pcW * (2 / 3);
        const pcX = (W - pcW) / 2;
        const pcBaseY = H * 0.5 - pcH / 2;
        const pcY = pcBaseY + slideOffset * (H - pcBaseY + pcH); // slide down off-screen
        // Alpha fade during slide
        const alpha = 1 - slideOffset * 0.7;
        ctx.globalAlpha = alpha;
        // Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(pcX + 6, pcY + 6, pcW, pcH);
        // White frame
        ctx.fillStyle = COLORS.paper;
        ctx.fillRect(pcX - 8, pcY - 8, pcW + 16, pcH + 40);
        ctx.strokeStyle = COLORS.brass;
        ctx.lineWidth = 1;
        ctx.strokeRect(pcX - 8, pcY - 8, pcW + 16, pcH + 40);
        // Photo (cover-fit)
        const ar = img.width / img.height;
        const boxAr = pcW / pcH;
        let dw, dh, dx, dy;
        if (ar > boxAr) {
          dh = pcH;
          dw = dh * ar;
          dx = pcX + (pcW - dw) / 2;
          dy = pcY;
        } else {
          dw = pcW;
          dh = dw / ar;
          dx = pcX;
          dy = pcY + (pcH - dh) / 2;
        }
        ctx.drawImage(img, dx, dy, dw, dh);
        // Caption strip
        ctx.fillStyle = COLORS.navyDeep;
        ctx.font = '600 13px "Space Mono", monospace';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        const label = `${stop.name}${stop.caption ? ' · ' + stop.caption : ''}`;
        ctx.fillText(label.slice(0, 48), pcX, pcY + pcH + 12);
        ctx.globalAlpha = 1;
      }
    }
  }
}

const LEG_MS = 2600; // base ms per leg at speed = 1
const STOP_PAUSE_MS = 650;

/* ---------- Pure playback timeline ----------
   stateAt(t, legs) maps a timeline position t ∈ [0,1] to the full observable
   playback state: which leg, how far along it (by arc length), where the plane
   is, and which pins are "past". Deterministic — same t always renders the
   same frame. This is what makes seek, restart, and (later) MP4 export exact. */
function stateAt(t, legs) {
  if (!legs.length) {
    return { legIndex: 0, legT: 0, plane: null, isPast: () => false, finished: false };
  }
  // Per-leg real-time weights: flight time + stop pause after each leg.
  const legMs = LEG_MS;
  const pauseMs = STOP_PAUSE_MS;
  const totalMs = legs.length * legMs + (legs.length - 1) * pauseMs;
  const ms = Math.max(0, Math.min(1, t)) * totalMs;

  let legIndex = 0;
  let legT = 0;
  let inPause = false;

  // Walk through legs, each occupying [legStart, legEnd], then a pause.
  // At a boundary exactly equal to legEnd we stay on the current leg at t=1
  // (so the plane is parked at the arrived stop, not snapped forward).
  for (let i = 0; i < legs.length; i++) {
    const legStart = i * (legMs + pauseMs);
    const legEnd = legStart + legMs;
    if (ms <= legEnd || i === legs.length - 1) {
      legIndex = i;
      if (ms <= legStart) {
        legT = 0;
        inPause = i > 0; // sitting at a stop before departing
      } else {
        legT = Math.min(1, (ms - legStart) / legMs);
        inPause = false;
      }
      break;
    }
  }
  if (ms >= totalMs) {
    legIndex = legs.length - 1;
    legT = 1;
    inPause = false;
  }

  const leg = legs[legIndex];
  const tt = tAtFraction(leg.lut, legT);
  const pos = qPoint(leg.bz, tt);
  const tan = qTangent(leg.bz, tt);
  const angle = (Math.atan2(tan.y, tan.x) * 180) / Math.PI;
  const plane = { x: pos.x, y: pos.y, angle, inPause };

  // Which stop (if any) the plane is currently dwelling on: during a pause
  // after leg i, we're sitting at stop i+1 (the arrived destination).
  const finished = legIndex === legs.length - 1 && legT >= 1;
  let pausedAtStopIndex = null;
  let pauseProgress = 0; // 0..1 — how far into the pause (for postcard animation)
  if (inPause) {
    pausedAtStopIndex = legIndex + 1;
    // Compute progress within the pause window.
    const legEnd = legIndex * (legMs + pauseMs) + legMs;
    const msIntoPause = ms - legEnd;
    pauseProgress = Math.max(0, Math.min(1, msIntoPause / pauseMs));
  } else if (finished) {
    pausedAtStopIndex = legs.length; // final destination = stops.length
    pauseProgress = 1; // fully settled
  }

  return {
    legIndex,
    legT,
    plane,
    pausedAtStopIndex,
    pauseProgress,
    isPast: (stopIndex) => {
      // Stops we've fully left behind: indices < current leg's origin.
      if (stopIndex < legIndex) return true;
      // The origin of the current leg has been departed.
      if (stopIndex === legIndex) return true;
      // The destination of the current leg counts as past only when we've arrived.
      if (stopIndex === legIndex + 1 && legT >= 1) return true;
      return false;
    },
    finished,
  };
}

export default function TravelRouteMap() {
  const [stops, setStops] = useState([]);
  const [loaded, setLoaded] = useState(false);

  const [query, setQuery] = useState('');
  const [dateVal, setDateVal] = useState('');
  const [selectedCity, setSelectedCity] = useState(null);
  const [suggestions, setSuggestions] = useState([]);
  const [geocoding, setGeocoding] = useState(false);
  const [formError, setFormError] = useState('');
  const [hoveredId, setHoveredId] = useState(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState('');
  const [exportProgress, setExportProgress] = useState(0); // 0..1
  const [photoUploading, setPhotoUploading] = useState(null); // stop id while compressing
  const [photoError, setPhotoError] = useState('');
  const [aspectRatio, setAspectRatio] = useState('horizontal'); // 'horizontal' | 'vertical'
  const [draggedId, setDraggedId] = useState(null); // stop id being dragged
  const [dragOverId, setDragOverId] = useState(null); // stop id being hovered
  const [highlightedSuggestion, setHighlightedSuggestion] = useState(null); // keyboard nav index
  const [theme, setTheme] = useState(() => { try { return localStorage.getItem('flight-log:theme') || 'vintage'; } catch { return 'vintage'; } });

  // Apply the active theme's colors to the module-level COLORS so both SVG + canvas pick it up
  COLORS = THEME_PALETTES[theme] || THEME_PALETTES.vintage;

  // Decoded images ready for canvas drawing, keyed by stop id.
  const photoImagesRef = useRef({});

  // Single source of truth for playback position: milliseconds along the
  // timeline. The pure stateAt(t) function derives everything else from it.
  // playheadMsRef drives the rAF loop without re-rendering on every frame;
  // a state mirror is bumped once per frame to trigger render.
  const [playhead, setPlayhead] = useState(0); // ms, for rendering
  const playheadMsRef = useRef(0);
  const rafRef = useRef(null);
  const lastTsRef = useRef(null);
  const inputRef = useRef(null);
  const blurTimeoutRef = useRef(null);

  /* ---- persistence ----
     Prefer the host-provided window.storage API; fall back to localStorage
     so stops persist in a plain browser (the original code silently dropped
     persistence when window.storage was absent, which is the common case). */
  const loadedStopsRef = useRef(null);
  const storage = useMemo(() => {
    if (typeof window !== 'undefined' && window.storage && typeof window.storage.get === 'function' && typeof window.storage.set === 'function') {
      return {
        async get(key) {
          const res = await window.storage.get(key, false);
          return res && res.value != null ? res.value : null;
        },
        async set(key, value) {
          await window.storage.set(key, value, false);
        },
      };
    }
    if (typeof window !== 'undefined' && window.localStorage) {
      return {
        async get(key) {
          try { return window.localStorage.getItem(key); }
          catch (e) { return null; }
        },
        async set(key, value) {
          try { window.localStorage.setItem(key, value); }
          catch (e) { /* quota / private mode */ }
        },
      };
    }
    // No storage at all (SSR, restricted iframe) — no-op.
    return { async get() { return null; }, async set() {} };
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const saved = await storage.get('flight-log:stops');
        if (!cancelled && saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed)) {
            const migrated = migrateStops(parsed);
            loadedStopsRef.current = JSON.stringify(migrated);
            setStops(migrated);
          }
        }
      } catch (e) {
        /* no saved trip yet */
      } finally {
        if (!cancelled) setLoaded(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [storage]);

  // Persist on stops change — but only after the initial load completes.
  // The load effect's async setStops() can fire AFTER the save effect has
  // already run with the empty default state on first render; gating with
  // `loaded` alone isn't enough because setStops and setLoaded dispatch in
  // the same batch. Track a "load completed" timestamp and only save once
  // the stops array we'd write differs from what we loaded.
  useEffect(() => {
    if (!loaded) return;
    const json = JSON.stringify(stops);
    if (loadedStopsRef.current === null) {
      // First save-gate after load: compare against what we loaded.
      loadedStopsRef.current = json;
      return;
    }
    if (json !== loadedStopsRef.current) {
      loadedStopsRef.current = json;
      storage.set('flight-log:stops', json);
    }
  }, [stops, loaded, storage]);

  /* ---- derived route (manual order, not date) ---- */
  const sortedStops = useMemo(() => sortStops(stops), [stops]);

  const legs = useMemo(() => {
    const out = [];
    for (let i = 0; i < sortedStops.length - 1; i++) {
      const from = sortedStops[i];
      const to = sortedStops[i + 1];
      const bz = legBezier(from, to);
      const lut = buildArcLUT(bz);
      out.push({ from, to, d: arcPath(from, to), bz, lut });
    }
    return out;
  }, [sortedStops]);

  // Total timeline duration for the current route (flight + stop pauses).
  const totalMs = useMemo(
    () => (legs.length ? legs.length * LEG_MS + (legs.length - 1) * STOP_PAUSE_MS : 0),
    [legs.length]
  );

  const totalKm = useMemo(() => {
    let sum = 0;
    for (let i = 0; i < sortedStops.length - 1; i++) sum += haversineKm(sortedStops[i], sortedStops[i + 1]);
    return Math.round(sum);
  }, [sortedStops]);

  const tripDays = useMemo(() => {
    const dated = sortedStops.filter((s) => s.date);
    if (dated.length < 2) return 0;
    const first = new Date(dated[0].date + 'T00:00:00');
    const last = new Date(dated[dated.length - 1].date + 'T00:00:00');
    return Math.round((last - first) / 86400000);
  }, [sortedStops]);

  // When the route changes, snap playhead back to start and stop playing.
  const routeKey = sortedStops.map((s) => s.id).join(',');
  useEffect(() => {
    setIsPlaying(false);
    playheadMsRef.current = 0;
    setPlayhead(0);
    lastTsRef.current = null;
  }, [routeKey]);

  /* ---- animation loop: drive the single playhead value ---- */
  useEffect(() => {
    if (!isPlaying || totalMs === 0) {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      return;
    }
    const step = (ts) => {
      if (lastTsRef.current == null) lastTsRef.current = ts;
      const dt = ts - lastTsRef.current;
      lastTsRef.current = ts;

      let next = playheadMsRef.current + dt * speed;
      if (next >= totalMs) {
        next = totalMs; // hold at the very end
        playheadMsRef.current = next;
        setPlayhead(next);
        setIsPlaying(false);
        return;
      }
      playheadMsRef.current = next;
      setPlayhead(next);
      rafRef.current = requestAnimationFrame(step);
    };
    rafRef.current = requestAnimationFrame(step);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [isPlaying, speed, totalMs]);

  // Derive the visible frame from the playhead via the pure function.
  const frame = useMemo(
    () => stateAt(totalMs > 0 ? playhead / totalMs : 0, legs),
    [playhead, totalMs, legs]
  );
  const plane = frame.plane;

  /* ---- city search ---- */
  function handleQueryChange(v) {
    setQuery(v);
    setSelectedCity(null);
    setFormError('');
    setHighlightedSuggestion(null);
    const q = v.trim().toLowerCase();
    if (q.length < 2) {
      setSuggestions([]);
      return;
    }
    const starts = [];
    const contains = [];
    for (const c of CITIES) {
      const n = c.name.toLowerCase();
      if (n.startsWith(q)) starts.push(c);
      else if (n.includes(q) || c.country.toLowerCase().includes(q)) contains.push(c);
      if (starts.length >= 10) break;
    }
    setSuggestions([...starts, ...contains].slice(0, 10));
  }

  function pickSuggestion(c) {
    setSelectedCity(c);
    setQuery(`${c.name}, ${c.country}`);
    setSuggestions([]);
    setFormError('');
  }

  async function handleAdd() {
    if (!query.trim()) {
      setFormError('Enter a destination');
      return;
    }
    let city = selectedCity;
    if (!city) {
      const q = query.trim().toLowerCase();
      city = CITIES.find((c) => c.name.toLowerCase() === q || `${c.name}, ${c.country}`.toLowerCase() === q) || null;
    }
    if (!city) {
      setGeocoding(true);
      setFormError('');
      // Nominatim is a free, unmetered, shared OSM service — it can and does
      // hang silently. Abort + timeout so the "Finding…" state can't wedge.
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 8000);
      try {
        const res = await fetch(
          `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(query.trim())}`,
          { signal: controller.signal }
        );
        clearTimeout(timeoutId);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (data && data[0]) {
          city = {
            name: query.trim(),
            country: data[0].display_name ? data[0].display_name.split(',').pop().trim() : '',
            lat: parseFloat(data[0].lat),
            lng: parseFloat(data[0].lon),
          };
        }
      } catch (e) {
        clearTimeout(timeoutId);
        if (e.name === 'AbortError') {
          setFormError('Location lookup timed out — try again, or pick a city from the suggestions');
          setGeocoding(false);
          return;
        }
        /* network/CORS/parse errors: fall through to the "couldn't find" branch below */
      }
      setGeocoding(false);
    }
    if (!city || Number.isNaN(city.lat) || Number.isNaN(city.lng)) {
      setFormError("Couldn't find that place — try a nearby major city or check the spelling");
      return;
    }
    // Duplicate guard: same place (name + lat/lng) on the same date is a no-op
    // rather than a second pin stacked on top.
    const isDuplicate = stops.some(
      (s) =>
        s.name === city.name &&
        s.lat === city.lat &&
        s.lng === city.lng &&
        (!dateVal || s.date === dateVal)
    );
    if (isDuplicate) {
      setFormError('That stop is already on your trip');
      return;
    }
    const stop = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      name: city.name,
      country: city.country || '',
      lat: city.lat,
      lng: city.lng,
      date: dateVal || '', // optional, display-only
      caption: '',         // filled in Stage 3 (photo-attachment UI)
      order: stops.length ? Math.max(...stops.map((s) => s.order)) + 1 : 0,
    };
    setStops((prev) => [...prev, stop]);
    setQuery('');
    setDateVal('');
    setSelectedCity(null);
    setSuggestions([]);
    setFormError('');
    if (inputRef.current) inputRef.current.focus();
  }

  function removeStop(id) {
    setStops((prev) => {
      const stop = prev.find((s) => s.id === id);
      if (stop && stop.photoId) deletePhoto(stop.photoId);
      delete photoImagesRef.current[id];
      const remaining = prev.filter((s) => s.id !== id);
      // Re-compact order values after removal so indices stay gapless
      return sortStops(remaining).map((s, i) => ({ ...s, order: i }));
    });
  }

  function moveStop(id, dir) {
    // dir = -1 (up) | +1 (down) in the *manual order*
    setStops((prev) => {
      const sorted = sortStops(prev);
      const idx = sorted.findIndex((s) => s.id === id);
      const swapWith = idx + dir;
      if (idx === -1 || swapWith < 0 || swapWith >= sorted.length) return prev;
      const next = [...sorted];
      [next[idx], next[swapWith]] = [next[swapWith], next[idx]];
      return next.map((s, i) => ({ ...s, order: i }));
    });
  }

  /* Google-Maps-style drag-to-reorder: drop the dragged stop onto another
     stop's position, shifting everything between. */
  function handleDrop(targetId) {
    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      setDragOverId(null);
      return;
    }
    setStops((prev) => {
      const sorted = sortStops(prev);
      const fromIdx = sorted.findIndex((s) => s.id === draggedId);
      const toIdx = sorted.findIndex((s) => s.id === targetId);
      if (fromIdx === -1 || toIdx === -1) return prev;
      const next = [...sorted];
      const [moved] = next.splice(fromIdx, 1);
      next.splice(toIdx, 0, moved);
      return next.map((s, i) => ({ ...s, order: i }));
    });
    setDraggedId(null);
    setDragOverId(null);
  }

  function updateCaption(id, caption) {
    setStops((prev) => prev.map((s) => (s.id === id ? { ...s, caption } : s)));
  }

  /* ---- photo attachment ---- */
  async function handlePhotoUpload(stopId, file) {
    setPhotoUploading(stopId);
    setPhotoError('');
    try {
      const dataUrl = await compressImage(file);
      const stop = stops.find((s) => s.id === stopId);
      // If there's an existing photo, delete its old storage key
      if (stop && stop.photoId) deletePhoto(stop.photoId);
      const photoId = `${stopId}-photo-${Date.now()}`;
      savePhoto(photoId, dataUrl);
      // Decode the image for canvas rendering
      const img = new Image();
      await new Promise((res, rej) => {
        img.onload = res;
        img.onerror = rej;
        img.src = dataUrl;
      });
      photoImagesRef.current[stopId] = img;
      setStops((prev) => prev.map((s) => (s.id === stopId ? { ...s, photoId } : s)));
    } catch (e) {
      setPhotoError(e.message || 'Could not upload photo');
    } finally {
      setPhotoUploading(null);
    }
  }

  function removePhoto(stopId) {
    const stop = stops.find((s) => s.id === stopId);
    if (stop && stop.photoId) deletePhoto(stop.photoId);
    delete photoImagesRef.current[stopId];
    setStops((prev) => prev.map((s) => (s.id === stopId ? { ...s, photoId: '' } : s)));
  }

  // Load any persisted photos into Image objects on mount / when stops change
  useEffect(() => {
    for (const s of stops) {
      if (s.photoId && !photoImagesRef.current[s.id]) {
        const dataUrl = loadPhoto(s.photoId);
        if (dataUrl) {
          const img = new Image();
          img.onload = () => { photoImagesRef.current[s.id] = img; };
          img.src = dataUrl;
        }
      }
    }
  }, [stops]);

  // Persist the theme choice
  useEffect(() => {
    try { localStorage.setItem('flight-log:theme', theme); } catch { /* ignore */ }
  }, [theme]);

  function handleKeyDown(e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (suggestions.length > 0 && !selectedCity) {
        // Quick-add: pick the top suggestion and add it in one stroke.
        pickSuggestionAndAdd(suggestions[highlightedSuggestion ?? 0]);
      } else {
        handleAdd();
      }
    } else if (e.key === 'ArrowDown' && suggestions.length > 0 && !selectedCity) {
      e.preventDefault();
      setHighlightedSuggestion((h) => (h == null ? 1 : (h + 1) % suggestions.length));
    } else if (e.key === 'ArrowUp' && suggestions.length > 0 && !selectedCity) {
      e.preventDefault();
      setHighlightedSuggestion((h) => (h == null ? suggestions.length - 1 : (h - 1 + suggestions.length) % suggestions.length));
    } else if (e.key === 'Escape' && suggestions.length > 0) {
      setSuggestions([]);
      setHighlightedSuggestion(null);
      e.stopPropagation(); // don't let Escape close other things (modals, etc.)
    }
  }

  // Pick a suggestion and add the stop immediately — the one-keystroke path.
  async function pickSuggestionAndAdd(city) {
    setSelectedCity(city);
    setQuery(`${city.name}, ${city.country}`);
    setSuggestions([]);
    setHighlightedSuggestion(null);
    setFormError('');
    // Add immediately with the picked city (no date — it's optional).
    const stop = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      name: city.name,
      country: city.country || '',
      lat: city.lat,
      lng: city.lng,
      date: dateVal || '', // keep whatever date the user already typed
      caption: '',
      order: stops.length ? Math.max(...stops.map((s) => s.order)) + 1 : 0,
    };
    const isDuplicate = stops.some(
      (s) => s.name === city.name && s.lat === city.lat && s.lng === city.lng && (!stop.date || s.date === stop.date)
    );
    if (isDuplicate) {
      setFormError('That stop is already on your trip');
      setQuery('');
      return;
    }
    setStops((prev) => [...prev, stop]);
    setQuery('');
    setDateVal('');
    setSelectedCity(null);
    setSuggestions([]);
    setHighlightedSuggestion(null);
    setFormError('');
    if (inputRef.current) inputRef.current.focus();
  }

  // Close the suggestion list when focus leaves the input — but wait a tick so
  // a mousedown on a suggestion still lands (blur fires before click).
  function handleInputBlur() {
    blurTimeoutRef.current = setTimeout(() => setSuggestions([]), 120);
  }

  function handleInputFocus() {
    if (blurTimeoutRef.current) {
      clearTimeout(blurTimeoutRef.current);
      blurTimeoutRef.current = null;
    }
  }

  function togglePlay() {
    if (legs.length === 0) return;
    // If we're at the end, restart from 0
    if (!isPlaying && playheadMsRef.current >= totalMs) {
      playheadMsRef.current = 0;
      setPlayhead(0);
    }
    lastTsRef.current = null;
    setIsPlaying((p) => !p);
  }

  function resetPlay() {
    setIsPlaying(false);
    playheadMsRef.current = 0;
    setPlayhead(0);
    lastTsRef.current = null;
  }

  /* ---- Video export (Tier A) ----
     Renders the trip animation to an offscreen canvas and records it with
     MediaRecorder. Runs in *real time* (the animation plays once, at 1x,
     and the stream is captured as it renders). Output is webm (Chrome/
     Firefox) or mp4 (Safari) — detected from MediaRecorder support. */
  async function exportVideo() {
    if (legs.length === 0 || exporting) return;
    setExporting(true);
    setExportError('');
    setExportProgress(0);

    try {
      const FPS = 30;
      const vertical = aspectRatio === 'vertical';
      const outW = vertical ? OUT_W : HORIZ_W;
      const outH = vertical ? OUT_H : HORIZ_H;
      const useCamera = vertical; // camera-follow only in vertical mode (Stage 4)
      const canvas = document.createElement('canvas');
      canvas.width = outW;
      canvas.height = outH;
      const ctx = canvas.getContext('2d');

      // Pick the best supported mime type.
      const candidates = [
        'video/webm;codecs=vp9',
        'video/webm;codecs=vp8',
        'video/webm',
        'video/mp4;codecs=avc1',
        'video/mp4',
      ];
      const mimeType = candidates.find((t) => MediaRecorder.isTypeSupported(t));
      if (!mimeType) {
        throw new Error('This browser cannot record video (no MediaRecorder support)');
      }

      // Render one warm-up frame before recording starts so the first
      // captured frame isn't blank.
      const title = sortedStops.length > 1 ? `${sortedStops[0].name} → ${sortedStops[sortedStops.length - 1].name}` : sortedStops[0]?.name || 'Trip';
      drawFrame(ctx, {
        frame: stateAt(0, legs), legs, sortedStops, totalKm,
        tripTitle: title, photoImages: photoImagesRef.current,
        outW, outH, useCamera,
        cam: useCamera ? cameraAt(stateAt(0, legs), legs, outW, outH) : null,
      });

      const stream = canvas.captureStream(FPS);
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 8_000_000 });
      const chunks = [];
      recorder.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) chunks.push(e.data);
      };

      const done = new Promise((resolve) => {
        recorder.onstop = resolve;
      });

      recorder.start(250);
      const t0 = performance.now();

      await new Promise((resolve) => {
        const tick = () => {
          const elapsed = performance.now() - t0;
          const t = Math.min(1, elapsed / totalMs);
          const frame = stateAt(t, legs);
          drawFrame(ctx, {
            frame, legs, sortedStops, totalKm,
            tripTitle: title, photoImages: photoImagesRef.current,
            outW, outH, useCamera,
            cam: useCamera ? cameraAt(frame, legs, outW, outH) : null,
          });
          setExportProgress(t);
          if (t >= 1) {
            resolve();
          } else {
            requestAnimationFrame(tick);
          }
        };
        requestAnimationFrame(tick);
      });

      // Small tail so the final frame is fully captured
      await new Promise((r) => setTimeout(r, 300));
      recorder.stop();
      await done;
      stream.getTracks().forEach((tr) => tr.stop());

      // Download
      const ext = mimeType.includes('mp4') ? 'mp4' : 'webm';
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `flight-log-${sortedStops[0].name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${Date.now()}.${ext}`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) {
      console.error('Export failed', e);
      setExportError(e.message || 'Export failed');
    } finally {
      setExporting(false);
      setExportProgress(0);
    }
  }

  const activeLeg = legs[Math.min(frame.legIndex, legs.length - 1)];
  const tripFinished = legs.length > 0 && frame.finished && !isPlaying;
  const atStart = playhead === 0 && !isPlaying && !tripFinished;

  return (
    <div className="flg-root">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Space+Mono:wght@400;700&family=Work+Sans:wght@400;500;600;700&display=swap');

        .flg-root {
          min-height: 100%;
          width: 100%;
          background:
            radial-gradient(ellipse at 20% -10%, ${COLORS.navyPanel} 0%, ${COLORS.navyDeep} 55%),
            ${COLORS.navyDeep};
          color: ${COLORS.parchment};
          font-family: 'Work Sans', system-ui, -apple-system, sans-serif;
          padding: 28px 18px 40px;
          box-sizing: border-box;
        }
        .flg-root * { box-sizing: border-box; }
        .flg-shell { max-width: 880px; margin: 0 auto; }

        .flg-eyebrow {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.22em;
          color: ${COLORS.brass};
          text-transform: uppercase;
        }
        .flg-title-row { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-top: 4px; }
        .flg-title {
          font-family: 'Fraunces', Georgia, serif;
          font-size: 34px;
          font-weight: 600;
          letter-spacing: -0.01em;
          margin: 0;
        }
        .flg-stats {
          font-family: 'Space Mono', monospace;
          font-size: 12px;
          color: ${COLORS.fog};
          display: flex;
          gap: 18px;
          flex-wrap: wrap;
          margin-top: 10px;
          letter-spacing: 0.04em;
        }
        .flg-stats b { color: ${COLORS.brass}; font-weight: 700; }

        .flg-panel {
          margin-top: 22px;
          background: rgba(27, 42, 74, 0.55);
          border: 1px solid ${COLORS.navyLine};
          border-radius: 10px;
          padding: 16px;
          backdrop-filter: blur(2px);
        }
        .flg-form-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: stretch; }
        .flg-input-wrap { position: relative; flex: 1 1 240px; min-width: 180px; }
        .flg-input-icon {
          position: absolute; left: 11px; top: 50%; transform: translateY(-50%);
          color: ${COLORS.fog}; pointer-events: none;
        }
        .flg-input, .flg-date {
          width: 100%;
          background: ${COLORS.navy};
          border: 1px solid ${COLORS.navyLine};
          color: ${COLORS.paper};
          border-radius: 7px;
          padding: 10px 12px 10px 34px;
          font-size: 14px;
          font-family: 'Work Sans', sans-serif;
          outline: none;
          transition: border-color 0.15s ease;
        }
        .flg-date { padding-left: 12px; flex: 0 0 150px; color-scheme: dark; }
        .flg-input:focus, .flg-date:focus { border-color: ${COLORS.brass}; }
        .flg-input::placeholder { color: ${COLORS.fog}; }

        .flg-add-btn {
          flex: 0 0 auto;
          display: flex; align-items: center; gap: 6px;
          background: ${COLORS.ember};
          color: ${COLORS.navyDeep};
          border: none;
          border-radius: 7px;
          padding: 10px 16px;
          font-weight: 700;
          font-size: 14px;
          cursor: pointer;
          transition: filter 0.15s ease, transform 0.1s ease;
          font-family: 'Work Sans', sans-serif;
        }
        .flg-add-btn:hover { filter: brightness(1.08); }
        .flg-add-btn:active { transform: translateY(1px); }
        .flg-add-btn:disabled { opacity: 0.55; cursor: default; }

        .flg-suggestions {
          position: absolute;
          top: calc(100% + 4px);
          left: 0; right: 0;
          background: ${COLORS.navy};
          border: 1px solid ${COLORS.navyLine};
          border-radius: 8px;
          overflow: hidden;
          z-index: 20;
          box-shadow: 0 10px 24px rgba(0,0,0,0.35);
        }
        .flg-suggestion {
          padding: 9px 12px;
          font-size: 13.5px;
          cursor: pointer;
          display: flex;
          justify-content: space-between;
          gap: 10px;
        }
        .flg-suggestion:hover { background: ${COLORS.navyPanel}; }
        .flg-suggestion-active { background: ${COLORS.navyPanel}; border-left: 2px solid ${COLORS.brass}; }
        .flg-suggestion span:last-child { color: ${COLORS.fog}; font-size: 12px; }
        .flg-suggestion-hint {
          padding: 6px 12px;
          font-size: 10.5px;
          color: ${COLORS.fog};
          font-family: 'Space Mono', monospace;
          border-top: 1px solid ${COLORS.navyLine};
          opacity: 0.8;
        }

        .flg-error {
          margin-top: 8px;
          font-size: 12.5px;
          color: ${COLORS.ember};
          font-family: 'Space Mono', monospace;
        }

        .flg-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
        .flg-chip {
          display: flex; align-items: center; gap: 7px;
          background: ${COLORS.navy};
          border: 1px solid ${COLORS.navyLine};
          border-radius: 999px;
          padding: 6px 6px 6px 12px;
          font-size: 12.5px;
        }
        .flg-chip-num {
          font-family: 'Space Mono', monospace;
          color: ${COLORS.navyDeep};
          background: ${COLORS.brass};
          border-radius: 999px;
          width: 17px; height: 17px;
          display: flex; align-items: center; justify-content: center;
          font-size: 10px; font-weight: 700;
          flex: none;
        }
        .flg-chip-date { color: ${COLORS.fog}; font-family: 'Space Mono', monospace; font-size: 11px; }
        .flg-chip-caption {
          background: transparent;
          border: 1px solid transparent;
          border-radius: 5px;
          color: ${COLORS.parchment};
          font-size: 11.5px;
          font-family: 'Work Sans', sans-serif;
          padding: 2px 5px;
          width: 68px;
          outline: none;
          transition: border-color 0.15s ease, background 0.15s ease;
        }
        .flg-chip-caption:hover { border-color: ${COLORS.navyLine}; }
        .flg-chip-caption:focus { border-color: ${COLORS.brass}; background: ${COLORS.navy}; }
        .flg-chip-caption::placeholder { color: ${COLORS.fog}; opacity: 0.7; font-style: italic; }
        .flg-chip-photo {
          width: 28px; height: 28px; object-fit: cover;
          border-radius: 5px; border: 1px solid ${COLORS.navyLine};
          cursor: pointer; flex: none;
        }
        .flg-chip-photo-btn {
          display: flex; align-items: center; justify-content: center;
          width: 22px; height: 22px; border-radius: 5px;
          color: ${COLORS.fog}; cursor: pointer;
          background: transparent; border: 1px solid transparent;
          transition: border-color 0.15s ease, color 0.15s ease;
        }
        .flg-chip-photo-btn:hover { border-color: ${COLORS.navyLine}; color: ${COLORS.brass}; }
        .flg-chip-photo-x {
          display: flex; align-items: center; justify-content: center;
          width: 18px; height: 18px; border-radius: 4px;
          color: ${COLORS.fog}; cursor: pointer; background: transparent; border: none;
        }
        .flg-chip-photo-x:hover { color: ${COLORS.ember}; }
        .flg-chip-grip { color: ${COLORS.fog}; cursor: grab; display: flex; align-items: center; padding: 0 2px; opacity: 0.5; transition: opacity 0.15s; }
        .flg-chip:hover .flg-chip-grip { opacity: 1; }
        .flg-chip-grip:active { cursor: grabbing; }
        .flg-chip-dragging { opacity: 0.4; transform: scale(0.96); }
        .flg-chip-dragover { border-color: ${COLORS.brass}; transform: scale(1.04); box-shadow: 0 0 0 2px ${COLORS.brass}; }
        .flg-chip-order { display: flex; flex-direction: column; margin-left: 2px; }
        .flg-chip-move {
          display: flex; align-items: center; justify-content: center;
          width: 16px; height: 12px; border-radius: 4px;
          color: ${COLORS.fog}; cursor: pointer; background: transparent; border: none;
          padding: 0;
        }
        .flg-chip-move:hover:not(:disabled) { background: ${COLORS.navyLine}; color: ${COLORS.paper}; }
        .flg-chip-move:disabled { opacity: 0.25; cursor: default; }
        .flg-chip-x {
          display: flex; align-items: center; justify-content: center;
          width: 20px; height: 20px; border-radius: 999px;
          color: ${COLORS.fog}; cursor: pointer; background: transparent; border: none;
        }
        .flg-chip-x:hover { background: ${COLORS.navyLine}; color: ${COLORS.paper}; }

        .flg-map-card {
          margin-top: 18px;
          position: relative;
          border-radius: 10px;
          overflow: hidden;
          border: 1px solid ${COLORS.navyLine};
        }
        .flg-map-card svg { display: block; width: 100%; height: auto; }
        .flg-pin-label {
          font-family: 'Space Mono', monospace;
          font-size: 8.5px;
          fill: ${COLORS.navyDeep};
          font-weight: 700;
        }
        .flg-tooltip {
          position: absolute;
          transform: translate(-50%, -132%);
          background: ${COLORS.paper};
          color: ${COLORS.navyDeep};
          padding: 5px 9px;
          border-radius: 6px;
          font-size: 12px;
          white-space: nowrap;
          pointer-events: none;
          box-shadow: 0 6px 16px rgba(0,0,0,0.35);
          font-family: 'Work Sans', sans-serif;
          z-index: 10;
        }
        .flg-tooltip b { font-family: 'Space Mono', monospace; font-weight: 700; }
        .flg-empty-hint {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          text-align: center;
          padding: 20px;
          font-family: 'Space Mono', monospace;
          font-size: 13px;
          color: ${COLORS.fog};
          letter-spacing: 0.03em;
          pointer-events: none;
        }

        .flg-board {
          margin-top: 16px;
          display: flex;
          gap: 12px;
          align-items: stretch;
          flex-wrap: wrap;
        }
        .flg-readout {
          flex: 1 1 260px;
          background: ${COLORS.navyDeep};
          border: 1px solid ${COLORS.navyLine};
          border-radius: 8px;
          padding: 12px 16px;
          font-family: 'Space Mono', monospace;
          display: flex;
          flex-direction: column;
          justify-content: center;
          min-height: 54px;
        }
        .flg-readout-main {
          font-size: 13.5px;
          color: ${COLORS.brass};
          letter-spacing: 0.05em;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }
        .flg-readout-sub {
          font-size: 11px;
          color: ${COLORS.fog};
          margin-top: 3px;
          letter-spacing: 0.04em;
        }
        .flg-controls { display: flex; gap: 8px; align-items: center; flex: 0 0 auto; }
        .flg-icon-btn {
          width: 42px; height: 42px;
          border-radius: 8px;
          border: 1px solid ${COLORS.navyLine};
          background: ${COLORS.navy};
          color: ${COLORS.parchment};
          display: flex; align-items: center; justify-content: center;
          cursor: pointer;
        }
        .flg-icon-btn:hover { border-color: ${COLORS.brass}; }
        .flg-icon-btn.primary { background: ${COLORS.ember}; color: ${COLORS.navyDeep}; border-color: ${COLORS.ember}; }
        .flg-icon-btn:disabled { opacity: 0.4; cursor: default; }
        .flg-speed {
          background: ${COLORS.navy};
          border: 1px solid ${COLORS.navyLine};
          color: ${COLORS.parchment};
          border-radius: 8px;
          font-family: 'Space Mono', monospace;
          font-size: 12px;
          padding: 0 8px;
          height: 42px;
        }
        .flg-export-btn {
          display: flex; align-items: center; gap: 6px;
          background: ${COLORS.brass};
          color: ${COLORS.navyDeep};
          border: none;
          border-radius: 8px;
          padding: 0 14px;
          height: 42px;
          font-weight: 700;
          font-size: 13px;
          font-family: 'Work Sans', sans-serif;
          cursor: pointer;
          transition: filter 0.15s ease;
        }
        .flg-export-btn:hover:not(:disabled) { filter: brightness(1.08); }
        .flg-export-btn:disabled { opacity: 0.55; cursor: default; }
        .flg-spin { animation: flg-spin 1s linear infinite; }
        @keyframes flg-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .flg-export-error {
          margin-top: 8px;
          font-size: 12.5px;
          color: ${COLORS.ember};
          font-family: 'Space Mono', monospace;
        }

        @media (max-width: 560px) {
          .flg-title { font-size: 26px; }
          .flg-date { flex: 1 1 130px; }
          .flg-board { flex-direction: column; }
          .flg-controls { justify-content: space-between; }
        }
      `}</style>

      <div className="flg-shell">
        <div className="flg-eyebrow">Route Atlas</div>
        <div className="flg-title-row">
          <h1 className="flg-title">Flight Log</h1>
        </div>
        {sortedStops.length > 0 && (
          <div className="flg-stats">
            <span><b>{sortedStops.length}</b> stop{sortedStops.length !== 1 ? 's' : ''}</span>
            {totalKm > 0 && <span><b>{totalKm.toLocaleString()}</b> km</span>}
            {tripDays > 0 && <span><b>{tripDays}</b> day{tripDays !== 1 ? 's' : ''}</span>}
          </div>
        )}

        <div className="flg-panel">
          <div className="flg-form-row">
            <div className="flg-input-wrap">
              <Search size={15} className="flg-input-icon" />
              <input
                ref={inputRef}
                className="flg-input"
                placeholder="Add a destination…"
                value={query}
                onChange={(e) => handleQueryChange(e.target.value)}
                onKeyDown={handleKeyDown}
                onBlur={handleInputBlur}
                onFocus={handleInputFocus}
              />
              {suggestions.length > 0 && (
                <div className="flg-suggestions">
                  {suggestions.map((c, si) => (
                    <div
                      key={`${c.name}-${c.lat}`}
                      className={`flg-suggestion${si === (highlightedSuggestion ?? 0) ? ' flg-suggestion-active' : ''}`}
                      onClick={() => pickSuggestionAndAdd(c)}
                    >
                      <span>{c.name}</span>
                      <span>{c.country}</span>
                    </div>
                  ))}
                  <div className="flg-suggestion-hint">↑↓ to navigate · Enter to add</div>
                </div>
              )}
            </div>
            <input
              type="date"
              className="flg-date"
              value={dateVal}
              onChange={(e) => setDateVal(e.target.value)}
              onKeyDown={handleKeyDown}
            />
            <button className="flg-add-btn" onClick={handleAdd} disabled={geocoding}>
              <Plus size={16} />
              {geocoding ? 'Finding…' : 'Add'}
            </button>
          </div>
          {formError && <div className="flg-error">{formError}</div>}

          {sortedStops.length > 0 && (
            <div className="flg-chips">
              {sortedStops.map((s, i) => (
                <div
                  key={s.id}
                  className={`flg-chip${draggedId === s.id ? ' flg-chip-dragging' : ''}${dragOverId === s.id && draggedId !== s.id ? ' flg-chip-dragover' : ''}`}
                  draggable
                  onDragStart={(e) => {
                    setDraggedId(s.id);
                    e.dataTransfer.effectAllowed = 'move';
                    e.dataTransfer.setData('text/plain', s.id);
                    try { e.dataTransfer.setData('text/uri-list', ''); } catch (_) { /* firefox needs this */ }
                  }}
                  onDragEnd={() => { setDraggedId(null); setDragOverId(null); }}
                  onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; setDragOverId(s.id); }}
                  onDragLeave={() => setDragOverId((cur) => (cur === s.id ? null : cur))}
                  onDrop={(e) => { e.preventDefault(); handleDrop(s.id); }}
                >
                  <span className="flg-chip-grip" title="Drag to reorder" aria-label={`Reorder ${s.name}`}>
                    <GripVertical size={12} />
                  </span>
                  <span className="flg-chip-num">{i + 1}</span>
                  {s.photoId && photoImagesRef.current[s.id] ? (
                    <img
                      className="flg-chip-photo"
                      src={photoImagesRef.current[s.id].src}
                      alt={s.name}
                      onClick={() => {/* preview larger */}}
                    />
                  ) : null}
                  <span>{s.name}</span>
                  {s.date ? <span className="flg-chip-date">{formatDateShort(s.date)}</span> : null}
                  <input
                    className="flg-chip-caption"
                    type="text"
                    value={s.caption || ''}
                    onChange={(e) => updateCaption(s.id, e.target.value)}
                    placeholder="note…"
                    maxLength={60}
                    aria-label={`Caption for ${s.name}`}
                  />
                  <label
                    className="flg-chip-photo-btn"
                    title={s.photoId ? 'Change photo' : 'Attach photo'}
                    aria-label={`Attach photo for ${s.name}`}
                  >
                    {photoUploading === s.id ? <Loader2 size={11} className="flg-spin" /> : <Camera size={11} />}
                    <input
                      type="file"
                      accept="image/*"
                      style={{ display: 'none' }}
                      onChange={(e) => {
                        const f = e.target.files && e.target.files[0];
                        if (f) handlePhotoUpload(s.id, f);
                        e.target.value = '';
                      }}
                    />
                  </label>
                  {s.photoId ? (
                    <button
                      className="flg-chip-photo-x"
                      onClick={() => removePhoto(s.id)}
                      aria-label={`Remove photo for ${s.name}`}
                      title="Remove photo"
                    >
                      <Trash2 size={10} />
                    </button>
                  ) : null}
                  <button className="flg-chip-x" onClick={() => removeStop(s.id)} aria-label={`Remove ${s.name}`}>
                    <X size={12} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flg-map-card">
          <svg viewBox={`0 0 ${MAP_W} ${MAP_H}`} xmlns="http://www.w3.org/2000/svg">
            <rect width={MAP_W} height={MAP_H} fill={COLORS.navy} />
            {[-150, -120, -90, -60, -30, 0, 30, 60, 90, 120, 150].map((lng) => (
              <line
                key={`v${lng}`}
                x1={((lng + 180) / 360) * MAP_W}
                y1={0}
                x2={((lng + 180) / 360) * MAP_W}
                y2={MAP_H}
                stroke={COLORS.fog}
                strokeOpacity={0.1}
                strokeWidth={0.5}
              />
            ))}
            {[-60, -30, 0, 30, 60].map((lat) => (
              <line
                key={`h${lat}`}
                x1={0}
                y1={((90 - lat) / 180) * MAP_H}
                x2={MAP_W}
                y2={((90 - lat) / 180) * MAP_H}
                stroke={COLORS.fog}
                strokeOpacity={0.1}
                strokeWidth={0.5}
              />
            ))}
            <path d={LAND_PATH} fill={COLORS.parchment} fillRule="evenodd" stroke={COLORS.navyDeep} strokeWidth={0.6} />

            {legs.map((leg, i) => {
              const isCurrent = i === frame.legIndex;
              const isPast = i < frame.legIndex;
              const isFuture = i > frame.legIndex;
              return (
                <g key={`${leg.from.id}-${leg.to.id}`}>
                  {/* Contrail glow: wide, semi-transparent stroke under the
                      flown/current legs — like a jet contrail on the map. */}
                  {(isPast || isCurrent) && (
                    <path
                      d={leg.d}
                      fill="none"
                      stroke={COLORS.ember}
                      strokeWidth={isCurrent ? 5 : 3.5}
                      strokeOpacity={isCurrent ? 0.18 : 0.1}
                      strokeLinecap="round"
                    />
                  )}
                  {/* Main route line: solid for past/current, dashed for future */}
                  <path
                    d={leg.d}
                    fill="none"
                    stroke={isFuture ? COLORS.emberDim : COLORS.ember}
                    strokeWidth={isCurrent ? 1.8 : isPast ? 1.4 : 1.1}
                    strokeDasharray={isFuture ? '4 3' : 'none'}
                    strokeLinecap="round"
                  />
                </g>
              );
            })}

            {sortedStops.map((s, i) => {
              const p = project(s.lat, s.lng);
              const isPast = frame.isPast(i);
              return (
                <g
                  key={s.id}
                  onMouseEnter={() => setHoveredId(s.id)}
                  onMouseLeave={() => setHoveredId(null)}
                  onClick={() => setHoveredId(hoveredId === s.id ? null : s.id)}
                  style={{ cursor: 'pointer' }}
                >
                  <circle cx={p.x} cy={p.y} r={7} fill={isPast ? COLORS.brass : COLORS.paper} stroke={COLORS.navyDeep} strokeWidth={1} />
                  <text x={p.x} y={p.y + 2.8} textAnchor="middle" className="flg-pin-label">
                    {i + 1}
                  </text>
                </g>
              );
            })}

            {plane && <PlaneGlyph x={plane.x} y={plane.y} angle={plane.angle} color={COLORS.ember} />}
          </svg>

          {sortedStops.length === 0 && (
            <div className="flg-empty-hint">Add two or more destinations above to plot your route</div>
          )}

          {hoveredId &&
            (() => {
              const s = sortedStops.find((x) => x.id === hoveredId);
              if (!s) return null;
              const p = project(s.lat, s.lng);
              return (
                <div
                  className="flg-tooltip"
                  style={{ left: `${(p.x / MAP_W) * 100}%`, top: `${(p.y / MAP_H) * 100}%` }}
                >
                  <b>{s.name}</b>{s.country ? `, ${s.country}` : ''}{s.date ? ` · ${formatDate(s.date)}` : ''}{s.caption ? ` · ${s.caption}` : ''}
                </div>
              );
            })()}
        </div>

        {legs.length > 0 && (
          <div className="flg-board">
            <div className="flg-readout">
              {atStart ? (
                <>
                  <div className="flg-readout-main">READY · {sortedStops[0].name.toUpperCase()} → {sortedStops[sortedStops.length - 1].name.toUpperCase()}</div>
                  <div className="flg-readout-sub">{legs.length} leg{legs.length !== 1 ? 's' : ''} · press play to fly the route</div>
                </>
              ) : tripFinished ? (
                <>
                  <div className="flg-readout-main">TOUCHED DOWN · {sortedStops[sortedStops.length - 1].name.toUpperCase()}</div>
                  <div className="flg-readout-sub">Trip complete — {totalKm.toLocaleString()} km over {tripDays} days</div>
                </>
              ) : (
                <>
                  <div className="flg-readout-main">
                    {activeLeg.from.name.toUpperCase()} → {activeLeg.to.name.toUpperCase()}
                  </div>
                  <div className="flg-readout-sub">{activeLeg.to.date ? `ARR ${formatDate(activeLeg.to.date)} · ` : ''}leg {frame.legIndex + 1} of {legs.length}</div>
                </>
              )}
              {exportError && <div className="flg-export-error" style={{ marginTop: 4 }}>{exportError}</div>}
              {photoError && <div className="flg-export-error" style={{ marginTop: 4 }}>{photoError}</div>}
            </div>
            <div className="flg-controls">
              <button className="flg-icon-btn" onClick={resetPlay} aria-label="Restart">
                <RotateCcw size={17} />
              </button>
              <button className="flg-icon-btn primary" onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Play'}>
                {isPlaying ? <Pause size={18} /> : <Play size={18} />}
              </button>
              <select className="flg-speed" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))}>
                <option value={0.5}>0.5×</option>
                <option value={1}>1×</option>
                <option value={2}>2×</option>
                <option value={4}>4×</option>
              </select>
              <select
                className="flg-speed"
                value={aspectRatio}
                onChange={(e) => setAspectRatio(e.target.value)}
                disabled={exporting}
                aria-label="Video aspect ratio"
                title="Export format"
              >
                <option value="horizontal">2:1 wide</option>
                <option value="vertical">9:16 vertical</option>
              </select>
              <select
                className="flg-speed"
                value={theme}
                onChange={(e) => setTheme(e.target.value)}
                disabled={exporting}
                aria-label="Map theme"
                title="Map color theme"
              >
                {Object.entries(THEME_LABELS).map(([key, label]) => (
                  <option key={key} value={key}>{label}</option>
                ))}
              </select>
              <button
                className="flg-export-btn"
                onClick={exportVideo}
                disabled={exporting || legs.length === 0}
                aria-label="Export video"
                title={exporting ? `Exporting… ${Math.round(exportProgress * 100)}%` : 'Export video'}
              >
                {exporting ? <Loader2 size={16} className="flg-spin" /> : <Download size={16} />}
                {exporting ? `${Math.round(exportProgress * 100)}%` : 'Export'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
